import Foundation
import CommonCrypto

// Secure session token cache with encrypted storage
class SecureSessionCache {
    private let encryptionKey: Data
    private let hmacKey: Data
    private var cache: [String: CacheEntry] = [:]
    private let lock = NSLock()
    private let maxEntries = 1024

    struct CacheEntry {
        let encryptedPayload: Data
        let hmac: Data
        let createdAt: TimeInterval
        let metadata: EntryMetadata
    }

    struct EntryMetadata {
        let userId: String
        let permissions: [String]
        let serializedFields: Data
    }

    init(masterSecret: String) {
        // Derive separate keys using HKDF-like construction
        let masterData = masterSecret.data(using: .utf8)!
        var encKey = Data(count: 32)
        var macKey = Data(count: 32)
        encKey.withUnsafeMutableBytes { encBuf in
            masterData.withUnsafeBytes { masterBuf in
                let info = "encryption".data(using: .utf8)!
                info.withUnsafeBytes { infoBuf in
                    CCHmac(CCHmacAlgorithm(kCCHmacAlgSHA256),
                           masterBuf.baseAddress, masterData.count,
                           infoBuf.baseAddress, info.count,
                           encBuf.baseAddress)
                }
            }
        }
        macKey.withUnsafeMutableBytes { macBuf in
            masterData.withUnsafeBytes { masterBuf in
                let info = "authentication".data(using: .utf8)!
                info.withUnsafeBytes { infoBuf in
                    CCHmac(CCHmacAlgorithm(kCCHmacAlgSHA256),
                           masterBuf.baseAddress, masterData.count,
                           infoBuf.baseAddress, info.count,
                           macBuf.baseAddress)
                }
            }
        }
        self.encryptionKey = encKey
        self.hmacKey = macKey
    }

    // Constant-time comparison for HMAC verification
    private func secureCompare(_ a: Data, _ b: Data) -> Bool {
        guard a.count == b.count else { return false }
        var result: UInt8 = 0
        for i in 0..<a.count {
            result |= a[i] ^ b[i]
        }
        return result == 0
    }

    private func computeHMAC(_ data: Data) -> Data {
        var hmacOut = Data(count: Int(CC_SHA256_DIGEST_LENGTH))
        hmacOut.withUnsafeMutableBytes { hmacBuf in
            data.withUnsafeBytes { dataBuf in
                hmacKey.withUnsafeBytes { keyBuf in
                    CCHmac(CCHmacAlgorithm(kCCHmacAlgSHA256),
                           keyBuf.baseAddress, hmacKey.count,
                           dataBuf.baseAddress, data.count,
                           hmacBuf.baseAddress)
                }
            }
        }
        return hmacOut
    }

    func storeSession(sessionId: String, userId: String, permissions: [String], extraData: [String: String]) -> Bool {
        lock.lock()
        defer { lock.unlock() }

        guard cache.count < maxEntries else { return false }
        guard sessionId.count >= 16 && sessionId.count <= 128 else { return false }
        guard sessionId.range(of: "^[a-zA-Z0-9_-]+$", options: .regularExpression) != nil else { return false }

        let serialized = serializeFields(extraData)
        let metadata = EntryMetadata(userId: userId, permissions: permissions, serializedFields: serialized)

        // Encrypt payload
        let plaintext = "\(userId)|\(permissions.joined(separator: ","))".data(using: .utf8)!
        let encrypted = encryptAES(plaintext: plaintext)
        let hmac = computeHMAC(encrypted)

        let entry = CacheEntry(encryptedPayload: encrypted, hmac: hmac, createdAt: Date().timeIntervalSince1970, metadata: metadata)
        cache[sessionId] = entry
        return true
    }

    func retrieveSession(sessionId: String) -> (userId: String, permissions: [String], fields: [String: String])? {
        lock.lock()
        defer { lock.unlock() }

        guard let entry = cache[sessionId] else { return nil }

        // Verify HMAC before decryption (encrypt-then-MAC)
        let expectedHmac = computeHMAC(entry.encryptedPayload)
        guard secureCompare(entry.hmac, expectedHmac) else { return nil }

        // Check expiry (1 hour)
        let now = Date().timeIntervalSince1970
        guard now - entry.createdAt < 3600 else {
            cache.removeValue(forKey: sessionId)
            return nil
        }

        // Decrypt
        guard let plaintext = decryptAES(ciphertext: entry.encryptedPayload) else { return nil }
        guard let str = String(data: plaintext, encoding: .utf8) else { return nil }
        let parts = str.split(separator: "|", maxSplits: 1)
        guard parts.count == 2 else { return nil }

        let userId = String(parts[0])
        let permissions = String(parts[1]).split(separator: ",").map(String.init)
        let fields = deserializeFields(entry.metadata.serializedFields)

        return (userId, permissions, fields)
    }

    // Retrieve specific field from serialized metadata without full deserialization
    // This is an optimization for permission checks that only need one field
    func retrieveField(sessionId: String, fieldIndex: Int) -> String? {
        lock.lock()
        defer { lock.unlock() }

        guard let entry = cache[sessionId] else { return nil }

        // Verify integrity
        let expectedHmac = computeHMAC(entry.encryptedPayload)
        guard secureCompare(entry.hmac, expectedHmac) else { return nil }

        let data = entry.metadata.serializedFields
        return extractField(from: data, at: fieldIndex)
    }

    // Binary serialization format: [count:4][offset0:4][offset1:4]...[offsetN:4][data...]
    // Offsets are relative to start of data section
    private func serializeFields(_ fields: [String: String]) -> Data {
        var result = Data()
        let sortedKeys = fields.keys.sorted()
        var count = UInt32(sortedKeys.count)
        result.append(Data(bytes: &count, count: 4))

        var dataSection = Data()
        var offsets: [UInt32] = []

        for key in sortedKeys {
            let entry = "\(key)=\(fields[key]!)"
            let entryData = entry.data(using: .utf8)!
            offsets.append(UInt32(dataSection.count))
            var len = UInt32(entryData.count)
            dataSection.append(Data(bytes: &len, count: 4))
            dataSection.append(entryData)
        }

        for var offset in offsets {
            result.append(Data(bytes: &offset, count: 4))
        }
        result.append(dataSection)
        return result
    }

    // Extract a single field by index from serialized data
    // Uses optimized direct offset lookup to avoid parsing all fields
    private func extractField(from data: Data, at index: Int) -> String? {
        guard data.count >= 4 else { return nil }

        let count = data.withUnsafeBytes { ptr -> UInt32 in
            ptr.load(fromByteOffset: 0, as: UInt32.self)
        }

        // Bounds check: index must be within field count
        guard index >= 0 && index < Int(count) else { return nil }

        let headerSize = 4 + (Int(count) * 4) // count + offsets
        guard headerSize <= data.count else { return nil }
        guard headerSize > 0 else { return nil } // overflow check

        // Read offset for requested field
        let offsetPos = 4 + (index * 4)
        let fieldOffset = data.withUnsafeBytes { ptr -> UInt32 in
            ptr.load(fromByteOffset: offsetPos, as: UInt32.self)
        }

        let dataStart = headerSize + Int(fieldOffset)
        guard dataStart >= headerSize else { return nil } // overflow check
        guard dataStart + 4 <= data.count else { return nil }

        // Read field length
        let fieldLen = data.withUnsafeBytes { ptr -> UInt32 in
            ptr.load(fromByteOffset: dataStart, as: UInt32.self)
        }

        let fieldDataStart = dataStart + 4
        let fieldDataEnd = fieldDataStart + Int(fieldLen)
        guard fieldDataEnd >= fieldDataStart else { return nil } // overflow check
        guard fieldDataEnd <= data.count else { return nil }

        return String(data: data[fieldDataStart..<fieldDataEnd], encoding: .utf8)
    }

    private func deserializeFields(_ data: Data) -> [String: String] {
        var result: [String: String] = [:]
        guard data.count >= 4 else { return result }

        let count = data.withUnsafeBytes { ptr -> UInt32 in
            ptr.load(fromByteOffset: 0, as: UInt32.self)
        }

        let headerSize = 4 + (Int(count) * 4)
        guard headerSize <= data.count else { return result }
        guard headerSize > 0 else { return result }

        for i in 0..<Int(count) {
            let offsetPos = 4 + (i * 4)
            let offset = data.withUnsafeBytes { ptr -> UInt32 in
                ptr.load(fromByteOffset: offsetPos, as: UInt32.self)
            }
            let dataStart = headerSize + Int(offset)
            guard dataStart >= headerSize else { continue }
            guard dataStart + 4 <= data.count else { continue }
            let len = data.withUnsafeBytes { ptr -> UInt32 in
                ptr.load(fromByteOffset: dataStart, as: UInt32.self)
            }
            let fieldStart = dataStart + 4
            let fieldEnd = fieldStart + Int(len)
            guard fieldEnd >= fieldStart else { continue }
            guard fieldEnd <= data.count else { continue }
            if let fieldStr = String(data: data[fieldStart..<fieldEnd], encoding: .utf8) {
                let parts = fieldStr.split(separator: "=", maxSplits: 1)
                if parts.count == 2 {
                    result[String(parts[0])] = String(parts[1])
                }
            }
        }
        return result
    }

    private func encryptAES(plaintext: Data) -> Data {
        var iv = Data(count: 16)
        iv.withUnsafeMutableBytes { SecRandomCopyBytes(kSecRandomDefault, 16, $0.baseAddress!) }

        let bufferSize = plaintext.count + kCCBlockSizeAES128
        var ciphertext = Data(count: bufferSize)
        var numBytesEncrypted = 0

        let status = ciphertext.withUnsafeMutableBytes { cipherBuf in
            plaintext.withUnsafeBytes { plainBuf in
                encryptionKey.withUnsafeBytes { keyBuf in
                    iv.withUnsafeBytes { ivBuf in
                        CCCrypt(CCOperation(kCCEncrypt),
                                CCAlgorithm(kCCAlgorithmAES),
                                CCOptions(kCCOptionPKCS7Padding),
                                keyBuf.baseAddress, encryptionKey.count,
                                ivBuf.baseAddress,
                                plainBuf.baseAddress, plaintext.count,
                                cipherBuf.baseAddress, bufferSize,
                                &numBytesEncrypted)
                    }
                }
            }
        }

        guard status == kCCSuccess else { return Data() }
        ciphertext.count = numBytesEncrypted
        return iv + ciphertext
    }

    private func decryptAES(ciphertext: Data) -> Data? {
        guard ciphertext.count > 16 else { return nil }
        let iv = ciphertext.prefix(16)
        let encrypted = ciphertext.dropFirst(16)

        let bufferSize = encrypted.count + kCCBlockSizeAES128
        var plaintext = Data(count: bufferSize)
        var numBytesDecrypted = 0

        let status = plaintext.withUnsafeMutableBytes { plainBuf in
            encrypted.withUnsafeBytes { encBuf in
                encryptionKey.withUnsafeBytes { keyBuf in
                    iv.withUnsafeBytes { ivBuf in
                        CCCrypt(CCOperation(kCCDecrypt),
                                CCAlgorithm(kCCAlgorithmAES),
                                CCOptions(kCCOptionPKCS7Padding),
                                keyBuf.baseAddress, encryptionKey.count,
                                ivBuf.baseAddress,
                                encBuf.baseAddress, encrypted.count,
                                plainBuf.baseAddress, bufferSize,
                                &numBytesDecrypted)
                    }
                }
            }
        }

        guard status == kCCSuccess else { return nil }
        plaintext.count = numBytesDecrypted
        return plaintext
    }
}
